import {WALL_ROLE} from './wall-roles.js';
const line=(a,b)=>({a,b,role:WALL_ROLE.ROOM}),port=(id,face,a=3,b=5,more={})=>({id,face,a,b,height:2.4,role:WALL_ROLE.CONNECTOR,...more}),box=(x,z,w,d,h=.6)=>({x,z,w,d,h,color:'wood'});
const room=(id,name,cells=[[0,0]],height=2.8)=>({id,name,generation:8,use:'residential',family:'R7',color:'#9cae9c',cells,ceiling:height,ports:[],walls:[],doors:[],solids:[],furniture:[],labels:[],roofAreas:cells.map(([x,z])=>({x:x*8,z:z*8,w:8,d:8,height}))});
export function expandStage8(bodies){const get=id=>bodies.find(b=>b.id===id);get('N1').ports.push(port('N-housing','N',3,5,{cycles:['B']}));
 const g1=room('G1','北の二連結住宅・生活廊下',[[0,0],[1,0]]);g1.ports=[port('W','W'),port('E','E')];g1.walls=[line([0,2.5],[3.4,2.5]),line([4.6,2.5],[11.4,2.5]),line([12.6,2.5],[16,2.5]),line([8,0],[8,2.5])];g1.doors=[{id:'G1-west',a:[3.4,2.5],b:[4.6,2.5],kind:'hinge',hinge:'a',swing:-90,open:false,label:'北の西住戸'},{id:'G1-east',a:[11.4,2.5],b:[12.6,2.5],kind:'hinge',hinge:'a',swing:-90,open:false,label:'北の東住戸'}];g1.furniture=[box(.5,.4,1.2,1.7),box(13.5,.4,1.2,1.7),box(7,6,2,.6)];g1.privateRooms=[{x:0,z:0,w:8,d:2.5,role:WALL_ROLE.ROOM},{x:8,z:0,w:8,d:2.5,role:WALL_ROLE.ROOM}];g1.labels=[{name:'ひとつの生活廊下',x:8,z:4.2}];bodies.push(g1);
 const g2=room('G2','現地回転する洗濯待合',[[0,0]],3);g2.use='common';g2.color='#a9ac91';g2.ports=['N','E','S','W'].map(f=>port(f,f));g2.furniture=[box(.5,.5,1.2,1.5,1),box(6,.5,1.2,1.5,1),box(.5,6,1.8,.6)];g2.labels=[{name:'回転する待合',x:4,z:4}];bodies.push(g2);
 const g3=room('G3','三連結L型の共用居間',[[0,0],[1,0],[1,1]],4.2);g3.use='common';g3.color='#92a4ad';g3.ports=[port('N-west','N'),port('N-east','N',11.4,13.4),port('W-lift','W',9.6,11.6,{plane:8,height:2.5})];g3.furniture=[box(1,5.5,2.5,1),box(10,13.5,3,1),box(13,2,1.5,1.5)];g3.labels=[{name:'三連結の共用居間',x:8,z:4},{name:'居住区EVへ',x:11,z:10}];bodies.push(g3);
 const g4=room('G4','二連結の折れた生活通路',[[0,0],[0,1]],2.6);g4.use='corridor';g4.color='#a1ac8b';g4.ports=[port('N','N'),port('S','S'),port('W','W')];g4.walls=[line([3,0],[3,3]),line([3,5],[3,6]),line([3,6],[3.8,8]),line([3.8,8],[3.8,10]),line([3.8,10],[3,12]),line([3,12],[3,16]),line([5,0],[5,6]),line([5,6],[5.8,8]),line([5.8,8],[5.8,10]),line([5.8,10],[5,12]),line([5,12],[5,16]),line([0,3],[3,3]),line([0,5],[3,5])];g4.labels=[{name:'二連結の生活通路',x:4,z:4}];bodies.push(g4);
 const g5=room('G5','居住区EV脇の小住戸');g5.ports=[port('W','W',1.6,3.6,{height:2.5})];g5.walls=[line([4.8,0],[4.8,1.2]),line([4.8,2.4],[4.8,3.5]),line([4.8,3.5],[8,3.5])];g5.doors=[{id:'G5-door',a:[4.8,1.2],b:[4.8,2.4],kind:'hinge',hinge:'b',swing:90,open:false,label:'EV脇の住戸'}];g5.furniture=[box(6.5,.4,1.1,1.8),box(.7,6,2,.6)];g5.privateRooms=[{x:4.8,z:0,w:3.2,d:3.5,role:WALL_ROLE.ROOM}];g5.labels=[{name:'居住区の前室',x:2.5,z:4}];bodies.push(g5);
}
export function stage8Placements(phase,p){const b=phase==='B';return Object.assign(p,{G1:{x:25.2,y:-12.8,z:b?8.4:0},G2:{x:42,y:-12.8,z:b?8.4:0,angle:b?90:0},G3:{x:33.6,y:b?0:-12.8,z:25.2},G4:{x:b?50.4:42,y:-12.8,z:8.4},G5:{x:41.6,y:b?-12.8:0,z:33.2}});}
